// A JWT is just three base64url strings joined by dots; the payload is
// readable by anyone, so never put secrets in it.
func main() {
	tok := "eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiIxMjMifQ.abc"
	parts := strings.Split(tok, ".")
	header, _ := base64.RawURLEncoding.DecodeString(parts[0])
	payload, _ := base64.RawURLEncoding.DecodeString(parts[1])
	fmt.Println(string(header))  // {"alg":"HS256"}
	fmt.Println(string(payload)) // {"sub":"123"}
	// parts[2] is the signature: proves the first two weren't tampered with.
}

