// Create then verify a token with golang-jwt/v5.
secret := []byte("k")
claims := jwt.MapClaims{"sub": "42", "exp": time.Now().Add(time.Hour).Unix()}
tok, _ := jwt.NewWithClaims(jwt.SigningMethodHS256, claims).SignedString(secret)

parsed, err := jwt.Parse(tok, func(t *jwt.Token) (any, error) {
	// Assert the algorithm before trusting the token!
	if _, ok := t.Method.(*jwt.SigningMethodHMAC); !ok {
		return nil, fmt.Errorf("unexpected alg: %v", t.Header["alg"])
	}
	return secret, nil // key used to verify the signature
})
fmt.Println(err == nil && parsed.Valid) // true

