func Auth(secret []byte) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			raw := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
			tok, err := jwt.Parse(raw, func(t *jwt.Token) (any, error) {
				if _, ok := t.Method.(*jwt.SigningMethodHMAC); !ok {
					return nil, fmt.Errorf("bad alg")
				}
				return secret, nil
			})
			if err != nil || !tok.Valid { // MUST check tok.Valid
				http.Error(w, "unauthorized", http.StatusUnauthorized)
				return // short-circuit: handler never runs
			}
			sub, _ := tok.Claims.GetSubject()
			ctx := context.WithValue(r.Context(), userKey, sub)
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}

// Hash at signup, compare at login; bcrypt embeds the salt + cost.
