// At login, compare the attempt against the stored hash.
err = bcrypt.CompareHashAndPassword(hash, []byte("s3cret"))
fmt.Println(err == nil) // true -> correct password, now issue a JWT
err = bcrypt.CompareHashAndPassword(hash, []byte("wrong"))
fmt.Println(err == nil) // false -> ErrMismatchedHashAndPassword

