package main

import (
	"fmt"
	"time"

	"github.com/golang-jwt/jwt/v5"
)

type AppClaims struct {
	UserID string `json:"uid"`
	Role   string `json:"role"`
	jwt.RegisteredClaims
}

var secret = []byte("super-secret-key")

func issue(uid, role string) (string, error) {
	claims := AppClaims{
		UserID: uid, Role: role,
		RegisteredClaims: jwt.RegisteredClaims{
			Issuer:    "auth-svc",
			ExpiresAt: jwt.NewNumericDate(time.Now().Add(15 * time.Minute)),
			IssuedAt:  jwt.NewNumericDate(time.Now()),
		},
	}
	return jwt.NewWithClaims(jwt.SigningMethodHS256, claims).SignedString(secret)
}

func verify(raw string) (*AppClaims, error) {
	claims := &AppClaims{}
	tok, err := jwt.ParseWithClaims(raw, claims, func(t *jwt.Token) (any, error) {
		if _, ok := t.Method.(*jwt.SigningMethodHMAC); !ok { // pin the algorithm
			return nil, fmt.Errorf("unexpected signing method: %v", t.Header["alg"])
		}
		return secret, nil
	})
	if err != nil || !tok.Valid { // BOTH conditions matter
		return nil, fmt.Errorf("invalid token: %w", err)
	}
	return claims, nil
}

func main() {
	tok, _ := issue("42", "admin")
	claims, err := verify(tok)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Printf("uid=%s role=%s iss=%s\n", claims.UserID, claims.Role, claims.Issuer)
}

