import (
	"fmt"
	"time"

	"github.com/golang-jwt/jwt/v5"
	"golang.org/x/crypto/bcrypt"
)

var secret = []byte("super-secret-key")

// storedHash simulates the bcrypt hash saved at signup time.
func storedHash() []byte {
	h, _ := bcrypt.GenerateFromPassword([]byte("correct-horse"), bcrypt.DefaultCost)
	return h
}

func login(hash []byte, attempt string) (string, error) {
	// bcrypt returns nil only when the password matches.
	if err := bcrypt.CompareHashAndPassword(hash, []byte(attempt)); err != nil {
		return "", fmt.Errorf("invalid credentials")
	}
	claims := jwt.MapClaims{
		"sub": "42",
		"exp": time.Now().Add(15 * time.Minute).Unix(),
	}
	return jwt.NewWithClaims(jwt.SigningMethodHS256, claims).SignedString(secret)
}

func main() {
	hash := storedHash()

	if _, err := login(hash, "wrong-pass"); err != nil {
		fmt.Println("bad login:", err)
	}

	tok, err := login(hash, "correct-horse")
	if err != nil {
		fmt.Println("unexpected:", err)
		return
	}
	fmt.Println("issued token, len:", len(tok) > 0)
}

