package main

import (
	"context"
	"fmt"
	"net/http"
	"strings"

	"github.com/golang-jwt/jwt/v5"
)

type ctxKey string

const userKey ctxKey = "user"

var secret = []byte("super-secret-key")

// Auth pins HS256, requires token.Valid, and injects the subject into ctx.
func Auth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		raw := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
		tok, err := jwt.Parse(raw, func(t *jwt.Token) (any, error) {
			// Pin the algorithm: reject anything that isn't HMAC (blocks alg=none).
			if _, ok := t.Method.(*jwt.SigningMethodHMAC); !ok {
				return nil, fmt.Errorf("unexpected alg: %v", t.Header["alg"])
			}
			return secret, nil
		})
		if err != nil || !tok.Valid { // reject invalid OR expired tokens
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return // short-circuit
		}
		sub, _ := tok.Claims.GetSubject()
		ctx := context.WithValue(r.Context(), userKey, sub)
		next.ServeHTTP(w, r.WithContext(ctx)) // carry identity inward
	})
}

