func sign(secret []byte, sub string, ttl time.Duration) string {
	claims := jwt.RegisteredClaims{
		Subject:   sub,
		ExpiresAt: jwt.NewNumericDate(time.Now().Add(ttl)),
	}
	s, _ := jwt.NewWithClaims(jwt.SigningMethodHS256, claims).SignedString(secret)
	return s
}

func TestAuthAllowsValid(t *testing.T) {
	secret := []byte("k")
	var seen string
	h := Auth(secret)(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		seen, _ = UserFromContext(r.Context())
		w.WriteHeader(http.StatusOK)
	}))
	req := httptest.NewRequest("GET", "/", nil)
	req.Header.Set("Authorization", "Bearer "+sign(secret, "u1", time.Hour))
	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, req)
	if rr.Code != http.StatusOK || seen != "u1" {
		t.Fatalf("code=%d user=%q, want 200 u1", rr.Code, seen)
	}
}

func TestAuthRejectsMissing(t *testing.T) {
	called := false
	h := Auth([]byte("k"))(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		called = true
	}))
	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, httptest.NewRequest("GET", "/", nil))
	if rr.Code != http.StatusUnauthorized || called {
		t.Fatalf("code=%d called=%v, want 401 and handler not called", rr.Code, called)
	}
}

