func Auth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		raw := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
		token, err := jwt.Parse(raw, func(t *jwt.Token) (any, error) {
			if _, ok := t.Method.(*jwt.SigningMethodHMAC); !ok {
				return nil, fmt.Errorf("bad alg")
			}
			return secret, nil
		})
		if err != nil || !token.Valid { // reject expired/invalid tokens
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r)
	})
}

type ctxKey string

const claimsKey ctxKey = "claims"

// WithClaims is what the auth middleware calls after validating the token.
func WithClaims(r *http.Request, c jwt.MapClaims) *http.Request {
	return r.WithContext(context.WithValue(r.Context(), claimsKey, c))
}

// RequireRole allows the request only if the JWT's role claim matches.
func RequireRole(role string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			claims, ok := r.Context().Value(claimsKey).(jwt.MapClaims)
			if !ok {
				http.Error(w, "forbidden", http.StatusForbidden)
				return
			}
			got, _ := claims["role"].(string) // missing/wrong type -> ""
			if got != role {
				http.Error(w, "forbidden", http.StatusForbidden)
				return // short-circuit: insufficient privileges
			}
			next.ServeHTTP(w, r)
		})
	}
}

// HashPassword returns a bcrypt hash (salt + cost embedded) as a string.
func HashPassword(pw string) (string, error) {
	b, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

// CheckPassword reports whether pw matches the stored bcrypt hash.
func CheckPassword(hash, pw string) bool {
	// CompareHashAndPassword returns nil ONLY on a match.
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}
